package android.text;
public class EditableString implements Editable { final CharSequence s; public EditableString(CharSequence s) { this.s = s == null ? "" : s; } public int length() { return s.length(); } public char charAt(int i) { return s.charAt(i); } public CharSequence subSequence(int a, int b) { return s.subSequence(a, b); } public String toString() { return s.toString(); } }